/* =====================================================================
   Курсова робота NVBD, варіант 6 «Поліклініка»
   Генерація даних. Скрипт 1. Довідники.
     - географія (регіони, міста), спеціальності, відділення
     - класи хвороб і хвороби МКХ-10, фармгрупи, лікарства, протипоказання
     - допоміжні таблиці генератора у схемі gen (видаляються наприкінці)
   ===================================================================== */
USE PolyclinicDB;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

IF SCHEMA_ID('gen') IS NULL EXEC('CREATE SCHEMA gen');
GO

/* ---------- Таблиця чисел 1..1 000 000 ---------- */
DROP TABLE IF EXISTS gen.Numbers;
SELECT TOP (1000000) ISNULL(CAST(ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) AS INT), 0) AS N
INTO gen.Numbers
FROM sys.all_objects a CROSS JOIN sys.all_objects b CROSS JOIN sys.all_objects c;
ALTER TABLE gen.Numbers ADD CONSTRAINT PK_gen_Numbers PRIMARY KEY (N);
GO

