/* ---------- Хвороби + профіль для генератора ----------
   Weight      — відносна частота звернень
   AgeProfile  — all / child / young / adult / elderly
   Gender      — NULL (обидві статі) / 'M' / 'F'
   Tag         — група лікарських призначень (gen.MedTag)
   ------------------------------------------------------ */
DROP TABLE IF EXISTS #D;
CREATE TABLE #D (ICDCode VARCHAR(10), Name NVARCHAR(200), Chapter VARCHAR(10), IsChronic BIT, IsInfectious BIT,
                 Severity TINYINT, Days SMALLINT, Season NVARCHAR(20), Specialty NVARCHAR(100),
                 Weight FLOAT, AgeProfile VARCHAR(10), Gender CHAR(1), Tag VARCHAR(20));

