INSERT dbo.Diseases (ICDCode, Name, CategoryID, IsChronic, IsInfectious, Severity, AvgTreatmentDays, Seasonality)
SELECT d.ICDCode, d.Name, c.CategoryID, d.IsChronic, d.IsInfectious, d.Severity, d.Days, d.Season
FROM #D d JOIN dbo.DiseaseCategories c ON c.ICDChapter = d.Chapter
ORDER BY d.ICDCode;

DROP TABLE IF EXISTS gen.DiseaseProfile;
SELECT ISNULL(ds.DiseaseID, 0) AS DiseaseID, ds.ICDCode, s.SpecialtyID, d.Weight, d.AgeProfile, d.Gender, d.Tag,
       ds.IsChronic, ds.Severity, ds.AvgTreatmentDays, ds.Seasonality, ds.CategoryID
INTO gen.DiseaseProfile
FROM #D d
JOIN dbo.Diseases ds   ON ds.ICDCode = d.ICDCode
JOIN dbo.Specialties s ON s.Name = d.Specialty;
ALTER TABLE gen.DiseaseProfile ADD CONSTRAINT PK_gen_DiseaseProfile PRIMARY KEY (DiseaseID);
GO

/* ---------- Ускладнення (для генерації діагнозів типу «Ускладнення») ---------- */
DROP TABLE IF EXISTS gen.Complications;
SELECT f.DiseaseID AS FromDiseaseID, t.DiseaseID AS ToDiseaseID, c.Prob
INTO gen.Complications
FROM (VALUES ('J06.9','J20.9',0.04), ('J06.9','J01.9',0.03), ('J06.9','H66.9',0.02),
             ('J00','J01.9',0.04), ('J10.1','J18.9',0.05), ('J10.1','J20.9',0.06),
             ('U07.1','J18.9',0.08), ('J20.9','J18.9',0.03), ('J03.9','H66.9',0.03),
             ('E11.9','H25.9',0.02), ('I10','I20.9',0.02), ('S52.5','M54.2',0.01)) c(FromICD, ToICD, Prob)
JOIN dbo.Diseases f ON f.ICDCode = c.FromICD
JOIN dbo.Diseases t ON t.ICDCode = c.ToICD;
GO

