INSERT dbo.Medications (Name, ActiveSubstance, GroupID, DosageForm, Manufacturer, UnitPrice, IsPrescriptionOnly)
SELECT m.Name, m.Substance, g.GroupID, m.Form, m.Manufacturer, m.Price, m.Rx
FROM #M m JOIN dbo.MedicationGroups g ON g.Name = m.GroupName;

-- Схема дозування для генератора призначень
DROP TABLE IF EXISTS gen.MedInfo;
SELECT ISNULL(md.MedicationID, 0) AS MedicationID, m.Dosage, m.PackSize, m.TimesPerDay
INTO gen.MedInfo
FROM #M m JOIN dbo.Medications md ON md.Name = m.Name;
ALTER TABLE gen.MedInfo ADD CONSTRAINT PK_gen_MedInfo PRIMARY KEY (MedicationID);

-- Відповідність «група призначень (Tag) → лікарство»
DROP TABLE IF EXISTS gen.MedTag;
SELECT CAST(t.value AS VARCHAR(20)) AS Tag, md.MedicationID
INTO gen.MedTag
FROM #M m
JOIN dbo.Medications md ON md.Name = m.Name
CROSS APPLY STRING_SPLIT(m.Tags, ',') t;
CREATE CLUSTERED INDEX CIX_gen_MedTag ON gen.MedTag (Tag, MedicationID);
GO

