SELECT 'Regions' AS TableName, COUNT(*) AS Cnt FROM dbo.Regions UNION ALL
SELECT 'Cities', COUNT(*) FROM dbo.Cities UNION ALL
SELECT 'Specialties', COUNT(*) FROM dbo.Specialties UNION ALL
SELECT 'Departments', COUNT(*) FROM dbo.Departments UNION ALL
SELECT 'DiseaseCategories', COUNT(*) FROM dbo.DiseaseCategories UNION ALL
SELECT 'Diseases', COUNT(*) FROM dbo.Diseases UNION ALL
SELECT 'MedicationGroups', COUNT(*) FROM dbo.MedicationGroups UNION ALL
SELECT 'Medications', COUNT(*) FROM dbo.Medications UNION ALL
SELECT 'Contraindications', COUNT(*) FROM dbo.Contraindications;
GO
